function officialSourceUrlForProtocol(protocol: ModelProtocol) {
  if (protocol === 'gemini-generate-content' || protocol === 'gemini-interactions') {
    return 'https://ai.google.dev/gemini-api/docs/models'
  }
  if (protocol === 'openai-images') return 'https://developers.openai.com/api/docs/guides/images-vision'
  if (protocol === 'openai-chat-completions' || protocol === 'openai-responses') {
    return 'https://developers.openai.com/api/docs/models'
  }
  if (protocol === 'bailian-openai-chat' || protocol === 'bailian-multimodal-generation') {
    return 'https://help.aliyun.com/en/model-studio/models'
  }
  if (protocol === 'ark-openai-chat' || protocol === 'ark-images') {
    return 'https://www.volcengine.com/docs/82379'
  }
  if (protocol === 'openrouter-images') {
    return 'https://openrouter.ai/docs/guides/overview/multimodal/image-generation'
  }
  return 'https://openrouter.ai/docs/guides/overview/models'
}

function registryEntry(
  id: string,
  label: string,
  roles: ModelRole[],
  protocol: ModelProtocol,
  availabilityNotes: string,
  options: Partial<ModelRegistryEntry['capabilities']> = {},
  metadata: RegistryEntryMetadata = {},
): ModelRegistryEntry {
  const imageGeneration = roles.includes('image')
  const imageEditing = options.imageEditing === true
  const referenceImages = options.referenceImages ?? roles.includes('vision')
  return {
    id,
    label,
    vendor: metadata.vendor || 'Unknown',
    lifecycle: metadata.lifecycle || 'stable',
    releaseKind: metadata.releaseKind || '',
    lifecycleSourceUrl: metadata.lifecycleSourceUrl || '',
    recommended: metadata.recommended === true,
    requiresEntitlement: metadata.requiresEntitlement === true,
    ...(metadata.entitlement ? { entitlement: metadata.entitlement } : {}),
    inputModalities: metadata.inputModalities || (referenceImages ? ['text', 'image'] : ['text']),
    outputModalities: metadata.outputModalities || (imageGeneration ? ['image'] : ['text']),
    verified: metadata.verified !== false,
    verificationState: metadata.verificationState || (metadata.verified === false ? 'unverified' : 'registry'),
    selectable: metadata.selectable !== false,
    releasedAt: metadata.releasedAt ?? null,
    expirationDate: metadata.expirationDate ?? null,
    ...(metadata.expirationAt ? { expirationAt: metadata.expirationAt } : {}),
    earliestRetirementDate: metadata.earliestRetirementDate ?? null,
    ...(metadata.replacementModelId ? { replacementModelId: metadata.replacementModelId } : {}),
    ...(metadata.regions ? { regions: metadata.regions } : {}),
    roleProtocols: metadata.roleProtocols || Object.fromEntries(roles.map((role) => [role, protocol])),
    officialSourceUrl: metadata.officialSourceUrl || officialSourceUrlForProtocol(protocol),
    ...(metadata.disabledReason ? { disabledReason: metadata.disabledReason } : {}),
    roles,
    roleReasons: metadata.roleReasons || Object.fromEntries(roles.map((role) => [role, `${label} is registered for ${role}`])),
    protocol,
    availabilityNotes,
    capabilities: {
      maxReferenceImages: imageEditing ? 1 : referenceImages ? 3 : 0,
      referenceImages,
      imageGeneration,
      imageEditing,
      imageEditMode: imageGeneration ? (imageEditing ? 'direct-edit' : 'analyze-redraw') : 'none',
      ...options,
      refineResolutions: canonicalRefineResolutions(options.refineResolutions),
      aspectRatios: canonicalAspectRatios(options.aspectRatios),
      refineAspectRatios: canonicalAspectRatios(options.refineAspectRatios),
    },
  }
}

