export function refineInputIssue(caps: RefineControls | null | undefined, input: any, ratio = 'auto', resolution = 'auto'): string {
  if (input === undefined) return ''
  if (!input || typeof input !== 'object' || Array.isArray(input) || input.version !== 1 || Object.keys(input).some(k => !['version','references','mask','structured'].includes(k))) return '精修输入契约无效，请刷新页面后重试。'
  const refs = input.references ?? []
  if (!Array.isArray(refs)) return '辅助参考图必须为列表。'
  if (refs.length > Math.min(REFINE_PRODUCT_MAX_REFERENCES, Math.max(0, (caps?.maxImages || 1) - 1))) return `当前型号最多接收 ${Math.max(0, (caps?.maxImages || 1) - 1)} 张辅助参考图；原图占用 1 个名额。图片已保留，请移除部分参考图或切换模型。`
  if (1 + refs.length < (caps?.minImages || 1)) return `当前型号至少需要 ${caps!.minImages} 张图片（含原图），请补充辅助参考图。`
  if (caps?.maskRequired && !input.mask) return '当前型号必须提供遮罩；请标记修改区域后再提交。'
  for (const ref of refs) {
    if (!ref || typeof ref.objectKey !== 'string' || !ref.objectKey || ref.objectKey.length > 300 || !['content','layout','color','style'].includes(ref.purpose) || (ref.note !== undefined && (typeof ref.note !== 'string' || ref.note.length > 300)) || Object.keys(ref).some(k => !['objectKey','purpose','note'].includes(k))) return '参考图的文件、用途或说明无效。'
  }
  if (input.mask) {
    if (!caps?.mask) return '当前型号未接入遮罩编辑；遮罩已保留，请清除遮罩或切换模型。'
    if (typeof input.mask.objectKey !== 'string' || !input.mask.objectKey || input.mask.objectKey.length > 300 || Object.keys(input.mask).some(k => k !== 'objectKey')) return '遮罩文件无效。'
    if (refs.length && !caps.maskWithReferences) return '当前型号不能同时使用遮罩与辅助参考图；请移除参考图或清除遮罩。'
  }
  if (input.structured) {
    if (caps?.structured !== 'bria-fibo') return '当前型号未接入原生结构化编辑；表单已保留，请关闭结构化编辑或切换模型。'
    if (Object.keys(input.structured).some(k => !['object','attributes','relationship','preserve'].includes(k))) return '结构化编辑字段无效。'
    for (const key of ['object','attributes','relationship','preserve']) if (typeof input.structured[key] !== 'string' || !input.structured[key].trim() || input.structured[key].length > 500) return '请填写修改对象、目标属性、关系及保留约束（每项 1–500 字）。'
  }
  if (caps?.singleImageInheritsSize && !refs.length && (ratio !== 'auto' || resolution !== 'auto')) return '当前型号单图或遮罩编辑继承原图尺寸；请手动选择自动清晰度与自动比例。'
  return ''
}
export function refineReferencePrompt(input?: RefineInputs): string {
  const labels = {content:'内容',layout:'布局',color:'配色',style:'风格'}
  return input?.references?.length ? '\n图片 1 是待精修原图。辅助图片仅用于下列指定方面，不改变未要求修改的科研内容：\n' + input.references.map((r,i) => `图片 ${i+2}：${labels[r.purpose]}。${r.note || ''}`).join('\n') : ''
}
/** These are BRIA's native fields, not a JSON prompt passed to a text field. */
export function briaStructuredInstruction(input: NonNullable<RefineInputs['structured']>, instruction: string) {
  return {short_description: instruction, edit_instruction: instruction, objects: [{description: input.object, shape_and_color: input.attributes, relationship: input.relationship}], context: `必须保留：${input.preserve}`}
}

/** Region identity is public routing data; API keys remain in client memory. */
export type ProviderRegions = { minimax?: 'global' | 'cn' }
export const MINIMAX_REGIONS = {
  global: { label: '国际', apiBase: 'https://api.minimax.io/v1', keyUrl: 'https://platform.minimax.io/user-center/basic-information/interface-key' },
  cn: { label: '中国大陆', apiBase: 'https://api.minimax.cn/v1', keyUrl: 'https://platform.minimaxi.com/user-center/basic-information/interface-key' },
} as const

export function normalizeProviderRegions(value?: unknown): ProviderRegions {
  if (value === undefined) return {}
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid provider region configuration')
  const input = value as Record<string, unknown>
  if (Object.keys(input).some(key => key !== 'minimax')) throw new Error('Unsupported provider region configuration')
  if (input.minimax !== undefined && input.minimax !== 'global' && input.minimax !== 'cn') throw new Error('Unsupported MiniMax region')
  return input.minimax === undefined ? {} : { minimax: input.minimax }
}

export function minimaxRegion(regions?: unknown): 'global' | 'cn' {
  return normalizeProviderRegions(regions).minimax || 'global'
}

export function regionApiKeySlot(provider: string, regions?: unknown): string {
  return provider === 'minimax' ? `minimax:${minimaxRegion(regions)}` : provider
}

/** Legacy unscoped MiniMax credentials belong only to the international API. */
export function selectRegionApiKeys(keys: Record<string, string>, regions?: unknown): Record<string, string> {
  const selected = Object.fromEntries(Object.entries(keys).filter(([key]) => !key.includes(':')))
  const region = minimaxRegion(regions)
  selected.minimax = keys[`minimax:${region}`] ?? (region === 'global' ? keys.minimax || '' : '')
  return selected
}

export function modelAvailableInRegion(provider: string, model: { regions?: string[] }, regions?: unknown): boolean {
  if (provider !== 'minimax') return true
  const region = minimaxRegion(regions)
  // Old unscoped catalog entries described only the international endpoint.
  return model.regions?.includes(region) || (region === 'global' && (!model.regions?.length || model.regions.includes('global-endpoint'))) || false
}

/** The selected region projects the same catalog used for admission and execution. */
export function registryForRegions<T extends { providers?: Record<string, any> }>(registry: T | null, regions?: unknown): T | null {
  const entry = registry?.providers?.minimax
  if (!entry) return registry
  const models = entry.models.filter((model: { regions?: string[] }) => modelAvailableInRegion('minimax', model, regions))
  return { ...registry!, providers: { ...registry!.providers, minimax: { ...entry, models } } }
}

const {callOfficialImageChannel,buildOfficialImageRequest,STEP_IMAGE_SUBMISSION_CUTOFF} = (()=>{
/** Audited 2026-09-22: new SenseNova Token API and StepFun China ordinary API.
 * The provider only announced a date. Midnight China time is our conservative
 * product cutoff, not a provider-published retirement timestamp. */
const STEP_IMAGE_SUBMISSION_CUTOFF = '2026-10-09T16:00:00Z'
const SENSE_MODELS = new Set(['sensenova-u1.5-lite', 'sensenova-u1.5-fast'])
const STEP_MODELS = new Set(['step-2x-large', 'step-image-edit-2'])
const STEP_2X_SIZES = new Set(['256x256', '512x512', '768x768', '1024x1024', '1280x800', '800x1280'])
const STEP_EDIT_2_SIZES = new Set(['1024x1024', '768x1360', '896x1184', '1360x768', '1184x896'])

type OfficialImageRequest = {
  endpoint: string
  method: 'POST'
  headers: Record<string, string>
  body: Record<string, unknown> | FormData
  multipart: boolean
}
type FrozenImage = { bytes: Buffer; width: number; height: number; dataUrl: string }

function notSent(message: string): never {
  throw Object.assign(new Error(message), { terminal: true, localInputFailure: true, requestState: 'not_sent' })
}
function checkIdentity(input: ImageChannelInput) {
  if (input.provider !== 'sensenova' && input.provider !== 'stepfun') notSent('未核验此官方图片渠道，未发送请求。')
  if (!(input.provider === 'sensenova' ? SENSE_MODELS : STEP_MODELS).has(input.model)) notSent('该官方图片型号不在已核验目录中，未发送请求。')
  if (input.region && input.region !== 'cn') notSent('当前仅接入已核验的中国普通 API，请核对地区与密钥。')
}
/** The shared upload layer freezes all sources as PNG. Read its real header,
 * never a remote URL or a separately supplied, potentially different Data URL. */
function frozenPng(source: NonNullable<ImageChannelInput['source']>): FrozenImage {
  if (source.mimeType !== 'image/png' || !/^[A-Za-z0-9+/]+={0,2}$/.test(source.base64)) notSent('原图与参考图须为已冻结的 PNG，未发送请求。')
  const bytes = Buffer.from(source.base64, 'base64')
  if (bytes.toString('base64').replace(/=+$/, '') !== source.base64.replace(/=+$/, '') ||
      bytes.length < 24 || !bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ||
      bytes.toString('ascii', 12, 16) !== 'IHDR') notSent('原图或参考图的 PNG 内容无效，未发送请求。')
  const width = bytes.readUInt32BE(16), height = bytes.readUInt32BE(20)
  if (!width || !height) notSent('原图或参考图缺少有效像素尺寸，未发送请求。')
  return { bytes, width, height, dataUrl: 'data:image/png;base64,' + bytes.toString('base64') }
}
function dimensions(input: ImageChannelInput): { width: number; height: number } | undefined {
  const { width, height, size } = input.size
  let resolved: { width: number; height: number } | undefined
  if (width !== undefined || height !== undefined) {
    if (!Number.isInteger(width) || !Number.isInteger(height) || width! <= 0 || height! <= 0) notSent('图片宽高须为正整数，未发送请求。')
    resolved = { width: width!, height: height! }
  }
  if (size && size !== 'auto') {
    const match = /^(\d+)x(\d+)$/.exec(size)
    if (!match) notSent('图片尺寸必须先解析为实际宽高，未发送请求。')
    const named = { width: Number(match[1]), height: Number(match[2]) }
    if (!Number.isSafeInteger(named.width) || !Number.isSafeInteger(named.height) || !named.width || !named.height) notSent('图片尺寸无效，未发送请求。')
    if (resolved && (resolved.width !== named.width || resolved.height !== named.height)) notSent('图片尺寸字段不一致，未发送请求。')
    resolved = named
  }
  return resolved
}

/** Pure request preparation. size.width/height and size.size always describe
 * actual W/H; only this adapter converts Step Image Edit 2's HxW wire format. */
function buildOfficialImageRequest(input: ImageChannelInput): OfficialImageRequest {
  checkIdentity(input)
  if (!input.apiKey.trim() || /[\r\n]/.test(input.apiKey)) notSent('请填写所选中国渠道的有效 API Key。')
  if (!input.prompt.trim()) notSent('图片提示词不能为空，未发送请求。')
  if (input.edit && !input.source) notSent('图片编辑控制需要原图，未发送请求。')
  if ((input.edit?.references?.length || 0) !== (input.edit?.inputs.references?.length || 0)) notSent('辅助参考图与输入记录数量不一致，未发送请求。')
  if (input.edit?.mask || input.edit?.inputs.mask) notSent('该型号未核验遮罩编辑协议，未发送请求。')
  if (input.edit?.inputs.structured) notSent('该型号不支持结构化编辑字段，请使用编辑提示词。')
  const images = input.source ? [input.source, ...(input.edit?.references || [])].map(frozenPng) : []
  const maximum = input.provider === 'sensenova' ? 5 : 1
  if (images.length > maximum) notSent(`该型号最多接收 ${maximum} 张图片（包含原图），未发送请求。`)
  const resolved = dimensions(input)
  const headers: Record<string, string> = { Authorization: 'Bearer ' + input.apiKey }
  const base = input.provider === 'sensenova' ? 'https://token.sensenova.cn/v1' : 'https://api.stepfun.com/v1'
  const json = (path: string, body: Record<string, unknown>): OfficialImageRequest => ({
    endpoint: base + path, method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' }, body, multipart: false,
  })
  if (input.provider === 'sensenova') {
    if (resolved && (resolved.width < 512 || resolved.height < 512 || resolved.width > 4096 || resolved.height > 4096 ||
        resolved.width % 32 || resolved.height % 32 || resolved.width / resolved.height < 1 / 3 || resolved.width / resolved.height > 3)) {
      notSent('商汤图片每边须为 512–4096 像素、32 的倍数，比例须在 1:3 至 3:1，未发送请求。')
    }
    return json(images.length ? '/images/edits' : '/images/generations', {
      model: input.model, prompt: input.prompt, n: 1, size: resolved ? `${resolved.width}x${resolved.height}` : 'auto',
      output_format: 'png', response_format: 'url', watermark: true, prompt_extend: false,
      ...(images.length ? { images: images.map(image => ({ image_url: image.dataUrl })) } : {}),
    })
  }
  const maxPromptLength = input.model === 'step-2x-large' && images.length ? 1024 : 512
  if ([...input.prompt].length > maxPromptLength) notSent(`该型号当前操作的提示词最多 ${maxPromptLength} 个字符，未发送请求。`)
  if (input.model === 'step-2x-large') {
    if (images.some(image => image.bytes.length > 10 * 1024 * 1024 || image.width > 2048 || image.height > 2048)) {
      notSent('Step 2x 原图须不超过 10 MB、2048×2048 像素；未压缩或裁切，未发送请求。')
    }
    const size = resolved ? `${resolved.width}x${resolved.height}` : '1024x1024'
    if (!STEP_2X_SIZES.has(size)) notSent('Step 2x 不支持所选输出尺寸，未发送请求。')
    return json(images.length ? '/images/image2image' : '/images/generations', {
      model: input.model, prompt: input.prompt, n: 1, size, response_format: 'url', steps: 50, cfg_scale: 6,
      // Required by the API; 0.5 is our explicit product choice from its example.
      ...(images.length ? { source_url: images[0].dataUrl, source_weight: 0.5 } : {}),
    })
  }
  if (!images.length) {
    const size = resolved ? `${resolved.height}x${resolved.width}` : '1024x1024'
    if (!STEP_EDIT_2_SIZES.has(size)) notSent('Step Image Edit 2 不支持所选输出尺寸，未发送请求。')
    return json('/images/generations', {
      model: input.model, prompt: input.prompt, n: 1, size, response_format: 'url', steps: 8, cfg_scale: 1,
    })
  }
  const image = images[0]
  if (image.width > 4096 || image.height > 4096) notSent('Step Image Edit 2 原图每边最多 4096 像素，未发送请求。')
  if (resolved && (resolved.width !== image.width || resolved.height !== image.height)) notSent('Step Image Edit 2 编辑仅保持原图尺寸，不能改为所选尺寸；未发送请求。')
  if (!resolved && (input.aspectRatio !== 'auto' || input.resolution !== 'auto')) notSent('Step Image Edit 2 编辑须选择自动保留原图尺寸，或明确选择与原图相同的宽高。')
  const form = new FormData()
  form.set('model', input.model)
  form.set('prompt', input.prompt)
  form.set('image', new Blob([new Uint8Array(image.bytes)], { type: 'image/png' }), 'source.png')
  form.set('response_format', 'url')
  form.set('steps', '8')
  form.set('cfg_scale', '1')
  // size is ignored by the provider; n and mask are not documented edit fields.
  return { endpoint: base + '/images/edits', method: 'POST', headers, body: form, multipart: true }
}

function unknownSubmission(): Error {
  return Object.assign(new Error('原同步图片请求结果未知，已阻止重复提交；请核对渠道记录与费用。'), {
    name: 'ImageChannelError', terminal: true, uncertain: true, pollOnly: false, requestState: 'unknown', recoveryAction: 'inspect_provider',
  })
}
function resultUrl(value: unknown): string {
  if (typeof value !== 'string' || !value) throw new Error('invalid result URL')
  const url = new URL(value)
  if (url.protocol !== 'https:' || url.username || url.password || url.port) throw new Error('invalid result URL')
  return url.href
}

/** One durable submission, with download-only recovery. No sync task ID can
 * make a new inference safe: neither provider documents a query endpoint. */
async function callOfficialImageChannel(input: ImageChannelInput, io: ImageChannelTransport): Promise<string> {
  checkIdentity(input)
  if (!io.pending || !io.checkpoint) notSent('当前后端缺少持久任务恢复能力，未发起渠道请求。')
  let current: ImageChannelCheckpoint | undefined
  try { current = await io.pending() } catch { notSent('读取原图片任务状态失败，未发起渠道请求。') }
  if (current && (current.provider !== input.provider || current.model !== input.model || current.failed ||
      (current.state?.region && current.state.region !== 'cn'))) {
    throw Object.assign(new Error('原渠道图片任务不可重放，请核对记录。'), { terminal: true, requestState: 'not_sent' })
  }
  const save = async (patch: Partial<ImageChannelCheckpoint>) => {
    const next = { ...current, provider: input.provider, model: input.model, ...patch }
    await io.checkpoint!(next)
    current = next
  }
  const failed = async (message: string, requestState = 'completed'): Promise<never> => {
    try { await save({ failed: true }) } catch { /* Existing submitting state still prohibits resubmission. */ }
    throw Object.assign(new Error(message), { name: 'ImageChannelError', terminal: true, requestState })
  }
  const download = async (url: string): Promise<string> => {
    try {
      // download() owns URL safety and redirect checks and accepts no credentials.
      return io.validate(await io.download(resultUrl(url)))
    } catch {
      throw Object.assign(new Error('原图片结果已保存，下载或校验未完成；可恢复下载，不会重新生成。'), {
        name: 'ImageChannelError', recoveryAction: 'resume', pollOnly: true, uncertain: false, requestState: 'completed',
      })
    }
  }
  const record = async (metadata: Record<string, unknown>) => {
    await io.record?.({
      provider: input.provider, model: input.model, requestId: current?.taskId || null,
      publicPrice: input.provider === 'stepfun'
        ? { amount: input.model === 'step-2x-large' ? 0.1 : 0.02, currency: 'CNY', unit: 'image', source: 'https://platform.stepfun.com/docs/zh/guides/pricing/details', checkedAt: '2026-09-22' }
        : { amount: null, currency: null, unit: 'points', source: 'https://platform.sensenova.cn/docs', checkedAt: '2026-09-22' },
      estimatedCost: null, reportedCost: null, invoiceCost: null, ...metadata,
    })
  }
  const existingUrl = current?.result?.url || current?.resultUrl
  if (existingUrl) return download(existingUrl)
  if (typeof current?.state?.inlineBase64 === 'string') {
    try { return io.validate(current.state.inlineBase64) } catch { return failed('原渠道图片内容校验失败；不会重新生成。') }
  }
  if (current) throw unknownSubmission()
  if (input.provider === 'stepfun' && io.now() >= Date.parse(STEP_IMAGE_SUBMISSION_CUTOFF)) {
    notSent('所选阶跃图片型号已到停服日期；原配置已保留，请手动选择其他型号。')
  }
  const prepared = buildOfficialImageRequest(input)
  try {
    await save({ state: { submitting: true, region: 'cn', operation: input.source ? 'editing' : 'generation' } })
  } catch { notSent('保存图片提交状态失败，未发起渠道请求。') }
  let response: Response
  try {
    response = await io.request(prepared.endpoint, {
      method: prepared.method, headers: prepared.headers,
      body: prepared.multipart ? prepared.body as FormData : JSON.stringify(prepared.body),
      redirect: 'error', signal: AbortSignal.timeout(600000),
    }, input.provider + ' image ' + input.model, 1)
  } catch { throw unknownSubmission() }
  if (response.status >= 400 && response.status < 500) {
    await response.body?.cancel().catch(() => {})
    return failed(`渠道拒绝图片请求（HTTP ${response.status}），请核对密钥、额度、限流及输入；未自动重发。`, 'rejected')
  }
  if (!response.ok) {
    await response.body?.cancel().catch(() => {})
    throw unknownSubmission()
  }
  let data: any
  try { data = await io.json(response, 80 * 1024 * 1024, input.provider + ' image result') } catch { throw unknownSubmission() }
  if (data?.error) return failed('渠道返回图片任务错误；请核对渠道记录与费用，未自动重发。')
  if (!Array.isArray(data?.data) || data.data.length !== 1 || !data.data[0] || typeof data.data[0] !== 'object') {
    return failed('渠道没有返回有效的单张图片结果；未自动重发。')
  }
  const row = data.data[0]
  if (row.finish_reason && row.finish_reason !== 'success') return failed('渠道图片任务未成功或输出被过滤；未自动重发。')
  const metadata = { usage: data.usage ?? null, seed: row.seed ?? null, finishReason: row.finish_reason ?? null }
  const requestId = typeof data.id === 'string' ? data.id : typeof data.request_id === 'string' ? data.request_id : undefined
  if (typeof row.url === 'string' && row.url) {
    let url: string
    try { url = resultUrl(row.url) } catch { return failed('渠道返回的图片地址无效；未自动重发。') }
    try { await save({ taskId: requestId, result: { url, metadata }, state: { region: 'cn', operation: input.source ? 'editing' : 'generation', submitting: false, completed: true } }) } catch { throw unknownSubmission() }
    try { await record(metadata) } catch {
      throw Object.assign(new Error('图片结果已保存，调用记录保存失败；可恢复下载，不会重新生成。'), { recoveryAction: 'resume', pollOnly: true, uncertain: false, requestState: 'completed' })
    }
    return download(url)
  }
  if (typeof row.b64_json === 'string' && row.b64_json) {
    let validated: string
    try { validated = io.validate(row.b64_json) } catch { return failed('渠道返回的图片内容校验失败；未自动重发。') }
    try { await save({ taskId: requestId, state: { region: 'cn', operation: input.source ? 'editing' : 'generation', submitting: false, completed: true, inlineBase64: validated } }) } catch { throw unknownSubmission() }
    try { await record(metadata) } catch {
      throw Object.assign(new Error('图片结果已保存，调用记录保存失败；可恢复读取，不会重新生成。'), { recoveryAction: 'resume', pollOnly: true, uncertain: false, requestState: 'completed' })
    }
    return validated
  }
  return failed('渠道响应缺少图片地址或图片内容；未自动重发。')
}

return {callOfficialImageChannel,buildOfficialImageRequest,STEP_IMAGE_SUBMISSION_CUTOFF}})()
const {callQianfanImageChannel,buildQianfanImageRequest} = (()=>{
const BASE = 'https://qianfan.baidubce.com/v2'
const PRICE_SOURCE = 'https://cloud.baidu.com/doc/qianfan/s/wmh4sv6ya'
const MUSE_SIZES = new Set(['1024x1024', '1280x720', '720x1280', '1152x864', '864x1152', '1328x1328', '1664x928', '928x1664', '1472x1104', '1104x1472'])
const CONTRACTS = {
  'musesteamer-air-image': { endpoint: '/musesteamer/images/generations', maxPrompt: 1000, amount: 0.05, scope: '1024x1024' },
  'qwen-image': { endpoint: '/images/generations', maxPrompt: 800, amount: 0.25, scope: '1024x1024' },
  'qwen-image-edit': { endpoint: '/images/edits', maxPrompt: 800, amount: 0.3, scope: 'per image' },
} as const
type QianfanImageModel = keyof typeof CONTRACTS

function invalid(message: string): never {
  throw Object.assign(new Error(message), { localInputFailure: true, requestState: 'not_sent' })
}
function unknownResult(): Error {
  return Object.assign(new Error('千帆同步图片请求结果未知；没有可核验的查询接口，不会重新提交。请核对原渠道记录。'), {
    name: 'ImageChannelError', terminal: true, uncertain: true, requestState: 'unknown', recoveryAction: 'stop',
  })
}
function terminal(message: string): Error {
  return Object.assign(new Error(message), { name: 'ImageChannelError', terminal: true, uncertain: false, requestState: 'rejected', recoveryAction: 'stop' })
}
function isModel(model: string): model is QianfanImageModel {
  return Object.prototype.hasOwnProperty.call(CONTRACTS, model)
}

function resolvedSize(input: ImageChannelInput): string {
  const supplied = input.size || {}
  let width: number | undefined, height: number | undefined
  if (supplied.size !== undefined) {
    if (typeof supplied.size !== 'string' || !/^[1-9]\d*x[1-9]\d*$/.test(supplied.size)) invalid('千帆图片尺寸须为已解析的宽x高。')
    ;[width, height] = supplied.size.split('x').map(Number)
  }
  if (supplied.width !== undefined || supplied.height !== undefined) {
    if (!Number.isSafeInteger(supplied.width) || !Number.isSafeInteger(supplied.height) || supplied.width! <= 0 || supplied.height! <= 0) invalid('千帆图片尺寸须同时提供整数宽高。')
    if (width !== undefined && (width !== supplied.width || height !== supplied.height)) invalid('千帆图片尺寸字段不一致。')
    width = supplied.width; height = supplied.height
  }
  if (width === undefined) {
    if (input.aspectRatio !== 'auto' || input.resolution !== 'auto') invalid('千帆所选比例或清晰度尚未解析为图片尺寸。')
    width = height = 1024
  }
  if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height)) invalid('千帆图片尺寸无效。')
  const size = `${width}x${height}`
  if (input.model === 'musesteamer-air-image') {
    if (!MUSE_SIZES.has(size)) invalid('MuseSteamer 不支持所选尺寸；未接受服务端自动回退尺寸。')
  } else if (width! < 512 || height! < 512 || width! > 2048 || height! > 2048) invalid('千帆 Qwen 输出图片宽高须分别在 512–2048 像素之间。')
  return size
}

/** Core freezes uploads as lossless PNG before this adapter. Do not infer dimensions from user metadata. */
function sourceDataUrl(source: NonNullable<ImageChannelInput['source']>): string {
  if (!source || typeof source !== 'object' || source.mimeType !== 'image/png' || typeof source.base64 !== 'string' || source.base64.length > 4 * Math.ceil(10 * 1024 * 1024 / 3)) invalid('千帆精修需要小于 10 MB 的规范化 PNG 原图。')
  const bytes = Buffer.from(source.base64, 'base64')
  if (bytes.toString('base64') !== source.base64 || bytes.length >= 10 * 1024 * 1024 || bytes.length < 33 || !bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) || bytes.readUInt32BE(8) !== 13 || bytes.toString('ascii', 12, 16) !== 'IHDR') invalid('千帆精修原图未符合冻结 PNG 契约。')
  const width = bytes.readUInt32BE(16), height = bytes.readUInt32BE(20)
  if (Math.min(width, height) < 128 || Math.max(width, height) / Math.min(width, height) > 4) invalid('千帆精修原图短边须至少 128 像素，长短边比例不超过 4。')
  const url = `data:image/png;base64,${source.base64}`
  if (source.dataUrl !== url) invalid('千帆精修原图字节与 Data URL 不一致。')
  return url
}

/** Ordinary mainland API only. Coding/Token Plan and internal Qianfan-Image are separate products. */
function buildQianfanImageRequest(input: ImageChannelInput): { endpoint: string; body: Record<string, unknown> } {
  if (input.provider !== 'qianfan' || !isModel(input.model)) invalid('千帆图片型号尚未核验，未发起请求。')
  if (input.region && input.region !== 'cn') invalid('千帆普通图片接口不能使用国际站账号或端点。')
  const contract = CONTRACTS[input.model]
  if (typeof input.prompt !== 'string' || !input.prompt.trim() || [...input.prompt].length > contract.maxPrompt) invalid(`千帆当前型号提示词须为 1–${contract.maxPrompt} 字符。`)
  const editing = input.model === 'qwen-image-edit'
  if (!editing && (input.source || input.edit)) invalid('千帆当前生成型号不接收原图或精修参数。')
  if (editing && !input.source) invalid('千帆 Qwen 图片编辑必须提供原图。')
  if (input.edit) {
    const values = input.edit.inputs
    if (!values || values.version !== 1 || Object.keys(values).some(key => !['version', 'references', 'mask', 'structured'].includes(key))) invalid('千帆精修输入契约无效。')
    if (input.edit.mask || values.mask || values.structured) invalid('千帆 Qwen 图片编辑不支持遮罩或原生结构化编辑。')
    if ((input.edit.references !== undefined && !Array.isArray(input.edit.references)) || (values.references !== undefined && !Array.isArray(values.references))) invalid('千帆辅助参考图必须为列表。')
    if ((input.edit.references?.length || 0) !== (values.references?.length || 0)) invalid('千帆参考图传输数量与输入不一致。')
  }
  const size = resolvedSize(input)
  const body: Record<string, unknown> = { model: input.model, prompt: input.prompt, size, prompt_extend: false }
  if (input.model === 'musesteamer-air-image') body.response_format = 'url'
  else { body.n = 1; body.watermark = false }
  if (editing) {
    const images = [input.source!, ...(input.edit?.references || [])]
    if (images.length > 3) invalid('千帆 Qwen 图片编辑最多接收 3 张图片，包含原图。')
    const urls = images.map(sourceDataUrl)
    body.image = urls.length === 1 ? urls[0] : urls
  }
  return { endpoint: BASE + contract.endpoint, body }
}

function resultUrl(value: unknown): string {
  if (typeof value !== 'string' || !value) throw unknownResult()
  let url: URL
  try { url = new URL(value) } catch { throw unknownResult() }
  // Official examples use HTTP BOS signed URLs. Changing only the scheme preserves the signature.
  if (url.protocol === 'http:' && /^[a-z0-9.-]+\.bcebos\.com$/.test(url.hostname) && !url.port) url.protocol = 'https:'
  if (url.protocol !== 'https:' || url.username || url.password || url.port) throw unknownResult()
  return url.href
}

function usageEvidence(value: unknown): Record<string, number> | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const clean: Record<string, number> = {}
  for (const field of ['prompt_tokens', 'completion_tokens', 'total_tokens', 'input_tokens', 'output_tokens', 'image_count', 'images']) {
    const amount = (value as Record<string, unknown>)[field]
    if (typeof amount === 'number' && Number.isFinite(amount) && amount >= 0) clean[field] = amount
  }
  return Object.keys(clean).length ? clean : null
}

function evidence(input: ImageChannelInput, metadata: any = {}) {
  const contract = isModel(input.model) ? CONTRACTS[input.model] : null
  return {
    provider: 'qianfan', model: input.model,
    requestId: typeof metadata.requestId === 'string' && /^[\w-]{1,256}$/.test(metadata.requestId) ? metadata.requestId : null,
    requestIdType: 'diagnostic-only', usage: usageEvidence(metadata.usage),
    publicPrice: { source: PRICE_SOURCE, checkedAt: '2026-09-22', amount: contract?.amount ?? null, currency: 'CNY', unit: 'image', scope: contract?.scope ?? null, billingVerified: false },
    estimatedCost: null, reportedCost: null, invoiceCost: null,
  }
}

/** A synchronous request is sent once. Diagnostic IDs do not imply a resumable provider task. */
async function callQianfanImageChannel(input: ImageChannelInput, io: ImageChannelTransport): Promise<string> {
  if (!io.pending || !io.checkpoint) invalid('当前后端缺少持久任务恢复能力，未发起千帆图片请求。')
  const previous = await io.pending()
  if (previous && (previous.provider !== input.provider || previous.model !== input.model)) throw terminal('原千帆图片记录与所选渠道或型号不一致，不会重新提交。')
  if (previous?.failed) throw terminal('原千帆图片请求已被拒绝或失败，不会重新提交。')
  const download = async (value: unknown, metadata?: any): Promise<string> => {
    const url = resultUrl(value)
    try {
      await io.record?.(evidence(input, metadata))
      return await io.download(url) // Asset download never receives the API key or authorization headers.
    } catch {
      throw Object.assign(new Error('已保存千帆图片结果，可恢复原链接下载；不会重新生成。'), {
        name: 'ImageChannelError', recoveryAction: 'resume', pollOnly: true, uncertain: false, requestState: 'unknown',
      })
    }
  }
  // Recovery precedes source, key and prompt validation: these are not needed to download an existing result.
  if (previous?.result || previous?.resultUrl) return download(previous.result?.url ?? previous.resultUrl, previous.result?.metadata)
  if (previous) throw unknownResult()
  const prepared = buildQianfanImageRequest(input)
  if (typeof input.apiKey !== 'string' || !input.apiKey.trim() || /[\r\n]/.test(input.apiKey)) invalid('千帆普通 API Key 无效。')
  const checkpoint: ImageChannelCheckpoint = { provider: input.provider, model: input.model, state: { phase: 'submitting', protocol: 'synchronous', submittedAt: io.now() } }
  await io.checkpoint(checkpoint) // Must finish durably BEFORE the potentially billed request.
  let data: any
  try {
    const response = await io.request(prepared.endpoint, {
      method: 'POST', headers: { Authorization: `Bearer ${input.apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(prepared.body), redirect: 'error', signal: AbortSignal.timeout(600000),
    }, `qianfan image ${input.model}`, 1)
    if (response.status >= 400 && response.status < 500 && response.status !== 408) {
      await response.body?.cancel()
      await io.checkpoint({ ...checkpoint, failed: true, state: { ...checkpoint.state, phase: 'rejected', httpStatus: response.status } })
      throw terminal(`千帆图片请求被拒绝（HTTP ${response.status}），未自动重发；实际费用需核对账单。`)
    }
    if (!response.ok) { await response.body?.cancel(); throw unknownResult() }
    data = await io.json(response, 1024 * 1024, `qianfan image ${input.model}`)
    if (data?.error || (data?.code !== undefined && data.code !== 0 && data.code !== '0') || data?.data?.[0]?.task_status === 'FAILED') {
      await io.checkpoint({ ...checkpoint, failed: true, state: { ...checkpoint.state, phase: 'rejected' } })
      throw terminal('千帆图片请求返回失败；不会重新提交，实际费用需核对账单。')
    }
    if (!Array.isArray(data?.data) || data.data.length !== 1) throw unknownResult()
    const url = resultUrl(data.data[0]?.url)
    const metadata = evidence(input, { requestId: data.id, usage: data.usage })
    await io.checkpoint({ ...checkpoint, state: { ...checkpoint.state, phase: 'completed' }, result: { url, metadata } })
    return await download(url, metadata)
  } catch (error: any) {
    if (error?.name === 'ImageChannelError') throw error
    throw unknownResult()
  }
}

return {callQianfanImageChannel,buildQianfanImageRequest}})()
